SELECT request_tracking_id, req_trck_cmd_type, req_trck_cmd_time, req_trck_cmd_status, result_callback_url, req_tracking_cmd, tracking_identifier, req_status_change_time, transmission_status, transmission_time, req_identifier FROM data_event_tracking_request_info where 1=1
and request_tracking_id = #{requestTrackingId}
and req_trck_cmd_status = #{reqTrckCmdStatus}
order by request_tracking_id desc

SELECT request_tracking_id, req_trck_cmd_type, req_trck_cmd_time, req_trck_cmd_status, result_callback_url, req_tracking_cmd, tracking_identifier, req_status_change_time, transmission_status, transmission_time, req_identifier FROM data_event_tracking_request_info where 1=1
and request_tracking_id = #{requestTrackingId}
or req_trck_cmd_status = #{reqTrckCmdStatus}
and req_trck_cmd_status = #{reqTrckCmdStatusErr}
order by request_tracking_id desc
